// Physician Assistant - Medical Case Challenge Practice Test 3. Original questions written for Valus from the
// HOSA 2026–27 test plan, slightly harder than the sample items: short clinical cases across body systems,
// assessment and diagnostic reasoning not covered in Practice Tests 1–2.
import {q, mix} from './q.js';
const CMDT='Papadakis et al., Current Medical Diagnosis & Treatment', MP='MedlinePlus';
const DP='Disease Process & Terminology (includes cancer & neoplasms)', INTEG='Integumentary', MSK='Musculoskeletal', CIRC='Circulatory & Lymphatic', RESP='Respiratory', DIG='Digestive', ENDO='Endocrine', NERV='Nervous & Senses', REPRO='Reproductive', URIN='Urinary', MENT='Mental Disorders', ASSESS='Patient Assessment', DX='Diagnosis';

export default {
 id:'physician-assistant-3',
 event:'Physician Assistant - Medical Case Challenge',
 title:'Practice Test 3',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'Current Medical Diagnosis & Treatment (CMDT) and MedlinePlus',
 plan:[{area:DP,weight:10},{area:INTEG,weight:4},{area:MSK,weight:6},{area:CIRC,weight:10},{area:RESP,weight:6},{area:DIG,weight:10},{area:ENDO,weight:6},{area:NERV,weight:8},{area:REPRO,weight:4},{area:URIN,weight:4},{area:MENT,weight:6},{area:ASSESS,weight:12},{area:DX,weight:14}],
 questions:mix([
  q(DP,'Which feature most strongly suggests a tumor is benign rather than malignant?','Slow growth within a capsule, without invasion',['Rapid growth that invades nearby tissue','Spread to lymph nodes and distant organs','Poorly differentiated cells with many mitoses'],'A','Benign tumors are usually encapsulated, well differentiated and slow growing, and they do not invade tissue or metastasize.',CMDT),
  q(DP,'What does the term “idiopathic” mean when applied to a disease?','Its cause is unknown',['It was caused by treatment','It is present from birth','It is spread by contact'],'B','Idiopathic means arising from an unknown cause, as in idiopathic pulmonary fibrosis; iatrogenic means caused by medical treatment.',CMDT),
  q(DP,'A sign that is found only in one specific disease, so its presence confirms the diagnosis, is called:','Pathognomonic',['Prodromal','Asymptomatic','Nonspecific'],'C','A pathognomonic finding is characteristic of one disease alone, such as Koplik spots in measles.',CMDT),
  q(DP,'A Pap test shows abnormal, disorganized cells that have not invaded tissue. What is this change called?','Dysplasia',['Atrophy','Hypertrophy','Metastasis'],'D','Dysplasia is abnormal cell growth and organization that is often precancerous; it can progress to carcinoma if untreated.',CMDT),
  q(DP,'An increase in the number of cells in an organ, as in the endometrium under estrogen, is called:','Hyperplasia',['Hypertrophy','Anaplasia','Necrosis'],'A','Hyperplasia is an increase in cell number; hypertrophy is an increase in cell size, as in a weight lifter’s muscles.',CMDT),
  q(INTEG,'A patient has well-defined red plaques with silvery scales on the elbows and knees, and pitted nails. What is the most likely diagnosis?','Psoriasis',['Atopic eczema','Tinea corporis','Seborrheic keratosis'],'B','Psoriasis causes silvery-scaled plaques on extensor surfaces such as elbows and knees, often with nail pitting.',CMDT),
  q(INTEG,'An older adult has burning pain, then a band of grouped blisters on one side of the chest that stops at the midline. What is the most likely cause?','Reactivated varicella-zoster virus (shingles)',['Contact dermatitis from a new laundry soap','Bacterial impetigo from skin scratching','An allergic reaction to a new medicine'],'C','Herpes zoster follows a single dermatome on one side and does not cross the midline; pain often comes before the rash.',CMDT),
  q(MSK,'A typist has numbness in the thumb, index and middle fingers that worsens at night. Tapping the wrist reproduces tingling. Which nerve is involved?','The median nerve',['The ulnar nerve','The radial nerve','The axillary nerve'],'D','Carpal tunnel syndrome compresses the median nerve at the wrist; a positive Tinel or Phalen sign supports the diagnosis.',CMDT),
  q(MSK,'After a sudden pivot during soccer, an athlete hears a pop and the knee swells. The tibia slides forward on the Lachman test. Which structure is torn?','The anterior cruciate ligament',['The medial collateral ligament','The patellar tendon','The lateral meniscus'],'A','The Lachman test checks for forward movement of the tibia, the most sensitive exam finding for an ACL tear.',CMDT),
  q(MSK,'An older adult has bony enlargements at the distal finger joints and pain that worsens with use. What is the most likely diagnosis?','Osteoarthritis',['Rheumatoid arthritis','Psoriatic arthritis','Septic arthritis'],'B','Heberden nodes at the distal finger joints and pain worse with activity are typical of osteoarthritis; rheumatoid arthritis spares these joints.',CMDT),
  q(CIRC,'A smoker has calf pain while walking that goes away with rest. The ankle-brachial index is 0.6. What is the diagnosis?','Peripheral artery disease',['Deep vein thrombosis','Chronic venous insufficiency','Lumbar spinal stenosis'],'C','Claudication with an ankle-brachial index below 0.9 indicates peripheral artery disease; 0.6 suggests moderate disease.',CMDT),
  q(CIRC,'Which murmur is holosystolic, heard best at the apex and radiates to the left axilla?','Mitral regurgitation',['Aortic regurgitation','Pulmonic stenosis','Mitral stenosis'],'D','Mitral regurgitation causes a blowing holosystolic murmur at the apex that radiates to the axilla.',CMDT),
  q(CIRC,'After a stab wound to the chest, a patient has low blood pressure, distended neck veins and muffled heart sounds. What is the most likely cause?','Cardiac tamponade',['Tension pneumothorax','Acute aortic stenosis','Massive pulmonary embolism'],'A','Beck’s triad of hypotension, jugular venous distention and muffled heart sounds suggests fluid compressing the heart (tamponade).',CMDT),
  q(CIRC,'A young adult has painless enlarged neck lymph nodes, night sweats and fever. A biopsy shows Reed–Sternberg cells. What is the diagnosis?','Hodgkin lymphoma',['Non-Hodgkin lymphoma','Acute lymphocytic leukemia','Infectious mononucleosis'],'B','Reed–Sternberg cells are the hallmark of Hodgkin lymphoma, which often presents in young adults with neck nodes and B symptoms.',CMDT),
  q(CIRC,'A patient who injects drugs has fever, a new heart murmur and painless red spots on the palms. What is the most likely diagnosis?','Infective endocarditis',['Acute rheumatic fever','Viral myocarditis','Pericardial effusion'],'C','Fever plus a new murmur suggests endocarditis; Janeway lesions are painless palm or sole spots, and injection drug use is a major risk factor.',CMDT),
  q(RESP,'A 30-year-old woman has a dry cough and painful red nodules on the shins. A chest X-ray shows bilateral hilar lymph node enlargement. What is the most likely diagnosis?','Sarcoidosis',['Lung adenocarcinoma','Tuberculosis','Asthma'],'D','Sarcoidosis forms noncaseating granulomas and commonly shows bilateral hilar lymphadenopathy, sometimes with erythema nodosum on the shins.',CMDT),
  q(RESP,'A child has repeated lung infections, poor weight gain and salty-tasting skin. Which test is used to diagnose the likely condition?','A sweat chloride test',['A tuberculin skin test','A methacholine challenge','A sputum Gram stain only'],'A','Cystic fibrosis is diagnosed by an elevated sweat chloride level; thick mucus causes lung infections and poor nutrient absorption.',CMDT),
  q(RESP,'A toddler has a barking, seal-like cough, hoarseness and stridor after a cold. A neck X-ray shows a steeple sign. What is the diagnosis?','Croup',['Epiglottitis','Bronchiolitis','Pertussis'],'B','Croup (laryngotracheobronchitis) is usually viral, causes a barking cough and narrows the subglottic airway, giving the steeple sign.',MP),
  q(DIG,'After a course of antibiotics, a hospitalized patient develops frequent watery diarrhea and cramping. Which infection is most likely?','Clostridioides difficile',['Helicobacter pylori','Hepatitis A virus','Giardia lamblia'],'C','Antibiotics disrupt normal gut flora, allowing C. difficile overgrowth; it is a leading cause of hospital-acquired diarrhea.',CMDT),
  q(DIG,'A patient with past abdominal surgery has cramping pain, vomiting, distention and no passage of gas. X-rays show air-fluid levels. What is the diagnosis?','Small bowel obstruction',['Acute appendicitis','Irritable bowel syndrome','Peptic ulcer disease'],'D','Adhesions from prior surgery are the most common cause of small bowel obstruction, which shows dilated loops with air-fluid levels.',CMDT),
  q(DIG,'A patient with years of untreated heartburn has a biopsy showing the lower esophagus lined with intestinal-type cells. What is this called?','Barrett esophagus',['Achalasia','Esophageal varices','Zenker diverticulum'],'A','Chronic acid reflux can cause Barrett esophagus, a metaplastic change that raises the risk of esophageal adenocarcinoma.',CMDT),
  q(DIG,'A patient with heavy alcohol use has ascites, spider angiomas and a low platelet count. What is the most likely condition?','Cirrhosis of the liver',['Acute gastritis','Chronic pancreatitis','Gallbladder cancer'],'B','Cirrhosis scars the liver, causing portal hypertension (ascites, low platelets from splenic sequestration) and skin findings such as spider angiomas.',CMDT),
  q(DIG,'A 4-week-old infant has forceful, non-bilious vomiting after feeds and an olive-shaped mass in the upper abdomen. What is the diagnosis?','Pyloric stenosis',['Intussusception','Hirschsprung disease','Midgut volvulus'],'C','Hypertrophic pyloric stenosis causes projectile non-bilious vomiting in infants about 2–8 weeks old, often with a palpable olive-shaped mass.',MP),
  q(ENDO,'A patient has kidney stones, bone pain, constipation and a high blood calcium with a high PTH. What is the most likely diagnosis?','Primary hyperparathyroidism',['Vitamin D deficiency','Primary hypoparathyroidism','Hypothyroidism'],'D','Primary hyperparathyroidism, usually from an adenoma, raises PTH and calcium, causing “stones, bones, groans and moans.”',CMDT),
  q(ENDO,'A patient with small cell lung cancer has a low serum sodium and concentrated urine while appearing euvolemic. What is the likely cause?','SIADH',['Diabetes insipidus','Addison disease','Cushing syndrome'],'A','The syndrome of inappropriate antidiuretic hormone makes the body retain water, diluting sodium; small cell lung cancer is a classic cause.',CMDT),
  q(ENDO,'A patient has episodes of severe headache, sweating, racing heart and very high blood pressure. Urine metanephrines are elevated. What is the diagnosis?','Pheochromocytoma',['Graves disease','Panic disorder','Carcinoid syndrome'],'B','A pheochromocytoma is an adrenal tumor that releases catecholamines in bursts; elevated metanephrines confirm excess catecholamines.',CMDT),
  q(NERV,'A 28-year-old woman had vision loss in one eye that improved, and now has numbness in her legs. MRI shows white matter lesions. What is the most likely diagnosis?','Multiple sclerosis',['Myasthenia gravis','Guillain–Barré syndrome','Amyotrophic lateral sclerosis'],'C','Multiple sclerosis causes episodes of central nervous system symptoms separated in time and space; optic neuritis is a common first sign.',CMDT),
  q(NERV,'Two weeks after a diarrheal illness, a patient develops weakness that starts in the legs and moves upward, with absent reflexes. What is the diagnosis?','Guillain–Barré syndrome',['Multiple sclerosis','Spinal cord tumor','Myasthenia gravis'],'D','Guillain–Barré syndrome is an autoimmune attack on peripheral nerves, often after Campylobacter infection, causing ascending weakness and areflexia.',CMDT),
  q(NERV,'A patient has a sudden painful red eye, blurred vision, halos around lights and a fixed, mid-dilated pupil. What is the emergency?','Acute angle-closure glaucoma',['Viral conjunctivitis','Age-related cataract formation','Dry eye syndrome'],'A','Acute angle-closure glaucoma sharply raises eye pressure, causing pain, halos and a mid-dilated pupil; it needs urgent treatment to save vision.',CMDT),
  q(NERV,'A patient has episodes of spinning vertigo lasting hours, with ringing, ear fullness and fluctuating hearing loss. What is the most likely diagnosis?','Ménière disease',['Benign positional vertigo','Acoustic neuroma','Otitis media'],'B','Ménière disease results from excess inner ear fluid and causes episodic vertigo, tinnitus, aural fullness and hearing loss.',CMDT),
  q(REPRO,'A young woman has irregular periods, acne, excess facial hair and many small ovarian cysts on ultrasound. What is the most likely diagnosis?','Polycystic ovary syndrome',['Endometriosis','Ovarian cancer','Primary ovarian insufficiency'],'C','PCOS is diagnosed by two of three: irregular ovulation, signs of high androgens and polycystic ovaries on ultrasound.',CMDT),
  q(REPRO,'A 68-year-old man has a weak urine stream, hesitancy and waking often at night to urinate. The prostate is smooth and enlarged. What is the most likely diagnosis?','Benign prostatic hyperplasia',['Locally invasive prostate cancer','Acute bacterial prostatitis','Bladder stones'],'D','BPH causes a smooth, symmetrically enlarged prostate and obstructive urinary symptoms; a hard, irregular nodule suggests cancer instead.',CMDT),
  q(URIN,'A patient with vomiting and diarrhea has a rising creatinine and a BUN-to-creatinine ratio above 20. What type of kidney injury is most likely?','Prerenal acute kidney injury',['Intrinsic kidney damage','Postrenal obstruction','Chronic kidney disease'],'A','Prerenal AKI comes from reduced blood flow to the kidneys, such as dehydration; a BUN:creatinine ratio above 20:1 supports it.',CMDT),
  q(URIN,'A woman leaks urine when she coughs, sneezes or laughs. What type of incontinence is this?','Stress incontinence',['Urge incontinence','Overflow incontinence','Functional incontinence'],'B','Stress incontinence results from weak pelvic floor support, so urine leaks when abdominal pressure rises; urge incontinence comes with a sudden need to go.',CMDT),
  q(MENT,'For a diagnosis of major depressive disorder, how long must symptoms be present?','At least 2 weeks',['At least 2 days','At least 6 months','At least 2 years'],'C','DSM criteria require five or more depressive symptoms, including low mood or loss of interest, for at least 2 weeks.',CMDT),
  q(MENT,'A teenager restricts food intake, has a very low body weight and an intense fear of gaining weight. What is the most likely diagnosis?','Anorexia nervosa',['Bulimia nervosa','Binge-eating disorder','Avoidant personality'],'D','Anorexia nervosa involves restriction leading to significantly low weight, fear of weight gain and a distorted body image.',CMDT),
  q(MENT,'Three months after a car crash, a patient has nightmares, flashbacks and avoids driving. What is the most likely diagnosis?','Posttraumatic stress disorder',['Acute stress disorder','Generalized anxiety disorder','Specific phobia only'],'A','PTSD requires symptoms such as intrusions, avoidance and arousal lasting more than 1 month after a trauma; acute stress disorder lasts under 1 month.',CMDT),
  q(ASSESS,'A patient’s blood pressure is 128/78 lying down and 104/70 after standing for 3 minutes. What does this show?','Orthostatic hypotension',['Normal blood pressure response','Hypertensive urgency','Widened pulse pressure'],'B','Orthostatic hypotension is a drop of at least 20 mm Hg systolic or 10 mm Hg diastolic within 3 minutes of standing; this systolic drop is 24.',CMDT),
  q(ASSESS,'In an eye exam note, what does “PERRLA” document?','Pupils equal, round and reactive to light and accommodation',['Peripheral vision equal, retina clear and lens aligned','Pressure equal in both eyes on retinal assessment','Pupils enlarged, reactive only to light, and asymmetric'],'C','PERRLA records that the pupils are equal, round and react to light and accommodation, a quick check of the eye and cranial nerves.',MP),
  q(ASSESS,'The lung base is dull to percussion, with absent breath sounds and decreased tactile fremitus. What is the most likely finding?','Pleural effusion',['Lobar pneumonia','Pneumothorax','Asthma attack'],'D','Fluid in the pleural space causes dullness and blocks sound and vibration; pneumonia increases fremitus, and pneumothorax is hyperresonant.',CMDT),
  q(ASSESS,'A patient with chest pain denies shortness of breath and sweating. What are these findings called?','Pertinent negatives',['Chief complaints','Objective signs','Family history'],'A','Pertinent negatives are symptoms that are absent but relevant to the differential diagnosis, and they help rule conditions in or out.',CMDT),
  q(ASSESS,'An adult weighs 90 kg and is 1.8 m tall. What is the BMI category?','Overweight (BMI about 27.8)',['Normal weight (BMI about 22.5)','Obesity (BMI about 31.2)','Underweight (BMI about 17.8)'],'B','BMI = weight (kg) ÷ height (m)². 90 ÷ 3.24 ≈ 27.8, which falls in the overweight range of 25 to 29.9.',CMDT),
  q(ASSESS,'In an adult, what capillary refill time is considered normal?','Less than 2 seconds',['Between 5 and 10 seconds','More than 4 seconds','Exactly 30 seconds'],'C','Capillary refill under 2 seconds suggests adequate peripheral perfusion; a delayed refill can signal shock or dehydration.',MP),
  q(DX,'A low-risk patient has possible pulmonary embolism. A D-dimer is normal. What can the clinician conclude?','PE is unlikely and can usually be ruled out',['PE is confirmed and needs treatment','A CT angiogram is still always needed','The test is useful only for heart attacks'],'D','The D-dimer is highly sensitive but not specific; a normal result in a low-probability patient makes PE very unlikely.',CMDT),
  q(DX,'Which blood test is most specific for diagnosing acute pancreatitis?','Serum lipase',['Serum amylase','ALT and AST','Serum bilirubin'],'A','Lipase rises within hours of pancreatitis and stays elevated longer and more specifically than amylase; three times normal supports the diagnosis.',CMDT),
  q(DX,'A teen has fever, sore throat, swollen posterior neck nodes and fatigue. Which test supports the likely diagnosis?','A heterophile antibody (Monospot) test',['A urine culture for bacterial growth','A tuberculin skin test reading','An ANA test for autoimmune disease'],'B','Infectious mononucleosis from Epstein–Barr virus is supported by a positive heterophile (Monospot) antibody test and atypical lymphocytes.',CMDT),
  q(DX,'An arterial blood gas shows pH 7.30, PaCO2 55 mm Hg and normal bicarbonate. What is the disorder?','Respiratory acidosis',['Metabolic acidosis','Respiratory alkalosis','Metabolic alkalosis'],'C','A low pH with a high PaCO2 means CO2 retention, which is respiratory acidosis, as seen in hypoventilation or COPD exacerbation.',CMDT),
  q(DX,'Which cerebrospinal fluid result best fits bacterial meningitis?','High neutrophils, high protein and low glucose',['High lymphocytes, normal glucose and normal protein','Normal cells, normal glucose and normal protein','Red blood cells only, with normal glucose levels'],'D','Bacterial meningitis causes a neutrophil-rich CSF with high protein and low glucose; viral meningitis usually has lymphocytes and normal glucose.',CMDT),
  q(DX,'A patient taking warfarin needs routine monitoring. Which test is used?','The INR',['The HbA1c','The TSH','The ESR'],'A','Warfarin effect is measured with the prothrombin time reported as the INR; most patients aim for an INR of 2 to 3.',CMDT),
  q(DX,'After a hike, a patient has an expanding red rash with central clearing at the site of a tick bite. How is the diagnosis usually made?','Clinically, from the rash and exposure history',['Only with a skin biopsy of the rash','Only with a spinal tap and culture','Only with an MRI of the affected limb'],'B','Erythema migrans in a person with tick exposure is enough to diagnose early Lyme disease; blood antibody tests are often negative early on.',CMDT)
 ],7944)
};
